        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();
        final int MOD = 998244353;
        if (k >= n) {
            System.out.println(0);
            return;
        }
        int c = n - (int) k;
        long[] fact = new long[2 * n];
        long[] invFact = new long[2 * n];
        fact[0] = 1;
        for (int i = 1; i < 2 * n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        invFact[2 * n - 1] = modInverse(fact[2 * n - 1], MOD);
        for (int i = 2 * n - 2; i >= 0; i--) {
