#include <bits/stdc++.h>
using namespace std;

long long power(long long base, int exp, int mod) {
    long long res = 1;
    long long cur = base % mod;
    while (exp > 0) {
        if (exp & 1) res = (res * cur) % mod;
        cur = (cur * cur) % mod;
        exp >>= 1;
    }
    return res;
}

long long nCr(int n, int r, vector<long long>& fact, vector<long long>& invFact, int mod) {
    return fact[n] * invFact[r] % mod * invFact[n - r] % mod;
}

long long modInverse(long long a, int m) {
    return power(a, m - 2, m);
}

