    for (int i = 2 * n - 2; i >= 0; i--) {
        invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
    }
    long long total = 0;
    for (int a = 1; a <= c; a++) {
        long long val = (power(a, n, MOD) * nCr(c, a, fact, invFact, MOD)) % MOD;
        total += (a % 2 == 0 ? 1 : -1) * val;
    }
    total = ((total % MOD) + MOD) % MOD;
    total = (total * nCr(n, c, fact, invFact, MOD)) % MOD;
